/** Thu 12 Nov 2026, 09:40 in Doha (UTC+3). */
export const FIXTURE_NOW = Date.parse("2026-11-12T09:40:00+03:00");
export const FIXTURE_NOW_ISO = new Date(FIXTURE_NOW).toISOString();

const MIN = 60_000;
const DAY = 24 * 60 * MIN;
/** A moment on today's date (Doha), or on an earlier one: `at("09:36")`, `at("20:15", 1)` is Wed 11 Nov. */
const at = (clock: string, daysBack = 0): string => {
  const [h, m] = clock.split(":").map(Number);
  const day = new Date(Date.parse("2026-11-12T00:00:00+03:00") - daysBack * DAY);
  return new Date(day.getTime() + (h * 60 + m) * MIN).toISOString();
};

