const lineSum = (items: OrderItem[]) => items.reduce((sum, it) => sum + (it.price ?? 0) * it.quantity, 0);

function build(spec: Spec): Order {
  const items = spec.items.map(([k, q]) => line(k, q));
  const zone = spec.zone ? ZONES[spec.zone] : null;
  const subtotal = lineSum(items);
  const fee = zone?.fee ?? 0;
  const total = subtotal - (spec.discount ?? 0) + fee;
  const created = at(spec.placed, spec.daysBack ?? 0);
  return {
    id: `ord-${spec.n}`,
    number: spec.n,
    status: spec.status,
    payment: spec.payment,
    ...(spec.link ? { pay_link: "open" as const } : {}),
    total,
    ...(spec.discount ? { subtotal, discount_total: spec.discount, discounts: [{ text: "Car care bundle · QAR 20 off over QAR 150", text_ar: "حزمة العناية بالسيارة · خصم 20 ر.ق فوق 150 ر.ق", amount: spec.discount }] } : {}),
    customer: spec.customer,
    contact_id: `c-${spec.n}`,
    phone: spec.phone,
    created_at: created,
    fulfilment: zone
      ? { mode: "delivery", fee: zone.fee, zone: zone.zone, zone_ar: zone.zone_ar, address: spec.address ?? null, note: spec.note ?? null, deliver_on: "2026-11-12" }
      : { mode: "pickup", fee: 0 },
    items,
    assigned: spec.by ? who(spec.by) : null,
  };
}

// ── the 212 done and 4 cancelled orders behind the counts ─

const PEOPLE = ["Aisha Hamad", "Mariam Saleh", "Khalid Nasser", "Omar Ali", "Fatima Darwish", "Yousef Hassan", "Rashid Mahmoud", "Noor Abdullah", "Layla Farouk", "Sara Haddad"];
const KEYS: Array<keyof typeof P> = ["wax250", "tyre", "oud", "cloth", "glass", "wash5", "wax500", "citrus", "newcar"];
const CANCELLED_AT = new Set([5, 61, 118, 190]);
const HISTORY_COUNT = 216;

function history(): Order[] {
  const rows: Order[] = [];
  for (let i = 0; i < HISTORY_COUNT; i += 1) {
    const n = 1028 - i;
    const items = [line(KEYS[(i * 5) % KEYS.length], 1 + (i % 3)), ...(i % 4 === 0 ? [line(KEYS[(i * 7 + 3) % KEYS.length], 1)] : [])];
    const daysBack = 1 + Math.floor(i / 8);
    const hour = 8 + ((i * 37) % 13);
    const minute = (i * 17) % 60;
    const created = new Date(Date.parse("2026-11-12T00:00:00+03:00") - daysBack * DAY + (hour * 60 + minute) * MIN).toISOString();
    const customer = PEOPLE[(i * 3) % PEOPLE.length];
    const cancelled = CANCELLED_AT.has(i);
    rows.push({
      id: `ord-${n}`,
      number: n,
      status: cancelled ? "cancelled" : "done",
      payment: cancelled ? "unpaid" : "paid",
      total: lineSum(items),
      customer,
      contact_id: `c-${n}`,
      phone: `9745555${String(1000 + ((i * 53) % 9000)).slice(0, 4)}`,
      created_at: created,
      items,
      assigned: who(["Salma", "Reem", "Bilal", "Yusuf"][i % 4]),
    });
  }
  return rows;
}

export const FIXTURE_ORDERS: Order[] = [...SPECS.map(build), ...history()];

// ── what the server computes, for the fixture API ─────────

const isOpen = (o: Order) => o.status === "new" || o.status === "confirmed" || o.status === "ready" || (o.payment === "unpaid" && o.status !== "cancelled");

export function countsOf(orders: Order[]): Counts {
  const real = orders.filter((o) => !o.test);
  const n = (f: (o: Order) => boolean) => real.filter(f).length;
  return {
    all: real.length,
    open: n(isOpen),
    new: n((o) => o.status === "new"),
    confirmed: n((o) => o.status === "confirmed"),
    ready: n((o) => o.status === "ready"),
    done: n((o) => o.status === "done"),
    cancelled: n((o) => o.status === "cancelled"),
    pickup: n((o) => o.fulfilment?.mode === "pickup"),
    delivery: n((o) => o.fulfilment?.mode === "delivery"),
  };
}

export function lateNewOf(orders: Order[], now: number): LateNew {
  const late = orders
    .filter((o) => !o.test && o.status === "new" && minutesSince(o.created_at, now) > LATE_MINUTES)
    .sort((a, b) => a.created_at.localeCompare(b.created_at));
  return { count: late.length, items: late.slice(0, 3).map((o) => ({ number: o.number, minutes: minutesSince(o.created_at, now) })) };
}

/** The rows a filtered list returns (the server's `list_orders_filtered`, in memory). */
export function filterOrders(orders: Order[], filters: OrderFilters): Order[] {
  const f = effectiveFilters(filters);
  const status = f.status || "open";
  let rows = orders.filter((o) => (status === "open" ? isOpen(o) : status === "all" ? true : o.status === status));
  if (f.payment && f.payment !== "all") rows = rows.filter((o) => o.payment === f.payment);
  if (f.mode && f.mode !== "all") rows = rows.filter((o) => o.fulfilment?.mode === f.mode);
  if (f.assigned === "none") rows = rows.filter((o) => !o.assigned);
  else if (f.assigned && f.assigned !== "all") rows = rows.filter((o) => o.assigned?.id === f.assigned);
  const term = (f.q ?? "").trim().toLowerCase().replace(/^#/, "");
  if (term) {
    rows = rows.filter(
      (o) =>
        String(o.number).includes(term) ||
        o.customer.toLowerCase().includes(term) ||
        o.phone.includes(term.replace(/\D/g, "") || "\u0000") ||
        o.items.some((it) => it.name.toLowerCase().includes(term) || (it.name_ar ?? "").includes(term)),
    );
  }
  return [...rows].sort((a, b) => (f.sort === "oldest" ? a.number - b.number : b.number - a.number));
}

export function listOf(orders: Order[], filters: OrderFilters, role: string): OrdersList {
  const rows = filterOrders(orders, filters);
  const offset = filters.offset ?? 0;
  const manager = role !== "agent";
  return {
    slug: "nuqta-car-care",
    orders: rows.slice(offset, offset + 50),
    total: rows.length,
    counts: countsOf(orders),
    late_new: lateNewOf(orders, FIXTURE_NOW),
    ...(manager ? { open_total: orders.filter((o) => !o.test && isOpen(o)).reduce((sum, o) => sum + o.total, 0) } : {}),
    access: { can_manage: manager, can_record_payments: manager, can_cancel: manager, receipt_on_payment: true },
    now: FIXTURE_NOW_ISO,
  };
}

// ── one order in full ─────────────────────────────────────

const OVERRIDES: Record<number, { windowUntil?: string; payRef?: string; paidAt?: string; method?: string }> = {
  1039: { windowUntil: "2026-11-13T09:10:00+03:00", payRef: "PL-2026-110391", paidAt: at("09:38"), method: "link" },
};

const plus = (iso: string, minutes: number) => new Date(Date.parse(iso) + minutes * MIN).toISOString();

export function detailOf(order: Order, role: string): OrderDetail {
  const manager = role !== "agent";
  const over = OVERRIDES[order.number] ?? {};
  const lines: OrderLine[] = order.items.map((it) => ({
    name: it.name,
    name_ar: it.name_ar,
    variant: it.variant,
    variant_ar: it.variant_ar,
    options: it.options,
    options_ar: it.options_ar,
    code: it.sku,
    quantity: it.quantity,
    unit: it.unit,
    unit_price: it.price ?? 0,
    line_total: (it.price ?? 0) * it.quantity,
  }));
  const taker = order.assigned?.name ?? null;
  const rank = { new: 0, confirmed: 1, ready: 2, done: 3, cancelled: 0 }[order.status];
  const activity: ActivityRow[] = [{ action: "placed", actor_name: "Customer", channel: "order link", created_at: order.created_at }];
  if (taker) activity.push({ action: "took", actor_name: taker, created_at: plus(order.created_at, 2) });
  if (rank >= 1) activity.push({ action: "confirmed", actor_name: taker ?? "ALYR", created_at: plus(order.created_at, 8) });
  if (rank >= 2) activity.push({ action: "ready", actor_name: taker ?? "ALYR", created_at: plus(order.created_at, 25) });
  if (rank >= 3) activity.push({ action: "done", actor_name: taker ?? "ALYR", created_at: plus(order.created_at, 50) });
  const paidAt = order.payment === "paid" ? over.paidAt ?? plus(order.created_at, 4) : null;
  const method = over.method ?? (order.payment === "paid" ? (order.fulfilment?.mode === "delivery" ? "link" : "cash") : null);
  if (paidAt) activity.push({ action: "paid", actor_name: method === "link" ? "ALYR" : taker ?? "Hana", detail: { method, amount_minor: order.total }, created_at: paidAt });
  activity.sort((a, b) => (a.created_at ?? "").localeCompare(b.created_at ?? ""));
  const document = manager && order.payment === "paid" && order.number >= 1036 ? { id: `doc-${order.number}`, kind: "receipt", number: `RC-${String(order.number - 1035).padStart(4, "0")}`, status: "issued" } : undefined;
  return {
    order: { ...order, ...(document ? { document } : {}) },
    lines,
    customer: {
      id: order.contact_id,
      name: order.customer,
      phone: order.phone,
      lang: order.number === 1037 ? "ar" : "en",
      window_until: over.windowUntil ?? plus(order.created_at, 24 * 60),
      opted_out: false,
    },
    payment: {
      state: order.payment,
      link: order.pay_link ?? null,
      link_sent_at: order.pay_link || over.method === "link" ? plus(order.created_at, 0) : null,
      paid_at: paidAt,
      method,
      reference: over.payRef ?? null,
      recorded_by: method === "link" ? null : taker ?? "Hana",
      amount_minor: paidAt ? order.total : null,
    },
    activity,
    ...(document ? { document } : {}),
    track_url: `/t/preview-${order.number}`,
    access: { can_manage: manager, can_record_payments: manager, can_cancel: manager, receipt_on_payment: true },
  };
}

